                      mevcut[id] ? { ...mevcut, [id]: { ...mevcut[id], yorum: sayi } } : mevcut
                    )
                  }
                  onPaylas={aniyiPaylas}
                  silOnayiAcik={silOnayi === ani.id}
                  onSilOnayi={(id) => setSilOnayi(silOnayi === id ? null : id)}
                  onSil={aniyiSil}
                  onNotKaydet={notuKaydet}
                  onEtiketKaldir={etiketiSil}
                />
              ))}
            </View>
          )}
        </>
      )}
    </ScrollView>

