    daire: {
      backgroundColor: renk.turuncuZemin,
      borderWidth: 2,
      borderColor: renk.turuncu,
      alignItems: 'center',
      justifyContent: 'center',
    },
    harf: {
      fontFamily: yazi.ekranBasligi,
      color: renk.turuncuYazi,
    },
  })

