    },
    {
      baslik: '10. Changes',
      paragraflar: ['If these terms change, the change is announced inside the app.'],
    },
    {
      baslik: '11. Governing law',
      paragraflar: ['These terms are subject to the law of the Republic of Turkey.'],
    },
  ],
}

export default en

